# এসএসসি উচ্চতর গণিত অধ্যায় ১৩ (ঘন জ্যামিতি): ১১ অধ্যায়ের সাথে মিশ্র ৬টি + পাঠ্যবইয়ের ৩২ নং (হুবহু) ও অনুশীলনীর ধাঁচে ৮টি (শুধু উত্তর)
# স্থানাঙ্ক অংশে এসএসসি সিলেবাস মানা হয়েছে (SYLLABUS.md): অনুপাতে বিভক্তি ও লম্ব/সমান্তরাল রেখার সমীকরণ নেই
import json, os, math
from sympy import Rational as R, sqrt, pi, simplify, symbols
x,y=symbols('x y')
D=lambda p,q: simplify(sqrt((p[0]-q[0])**2+(p[1]-q[1])**2))
Ar=lambda *P: abs(sum(P[i][0]*P[(i+1)%len(P)][1]-P[(i+1)%len(P)][0]*P[i][1] for i in range(len(P))))/R(2)
on=lambda e,p: simplify(e.subs({x:p[0],y:p[1]}))==0
f2=lambda v: f'{float(v):.2f}'
# ১ আয়তাকার ঘনবস্তু
A,B,C=(-2,1),(6,1),(6,6); l,b,h=D(A,B),D(B,C),3
assert (l,b)==(8,5) and 2*(l*b+b*h+h*l)==158 and sqrt(l**2+b**2+h**2)==7*sqrt(2)
cube=(7*sqrt(2))**3; ball=R(4,3)*pi*R(9,10)**3; assert simplify(cube-686*sqrt(2))==0 and int(float(cube/ball))==317
# ২ কোণক
O,A,P=(0,0),(6,0),(0,8); assert D(A,P)==10 and Ar(O,A,P)==24 and on(4*x+3*y-24,A) and on(4*x+3*y-24,P)
r,hh,L=6,8,10; assert pi*r*(L+r)==96*pi and R(1,3)*pi*r**2*hh==96*pi and f2(96*pi)=='301.59'
# ৩ ঘূর্ণনে কোণক
A,B,C=(1,1),(5,1),(1,4); assert D(A,B)==4 and D(A,C)==3 and D(B,C)==5 and Ar(A,B,C)==6 and on(3*x+4*y-19,B) and on(3*x+4*y-19,C)
assert R(1,3)*pi*3**2*4==12*pi and f2(12*pi)=='37.70' and pi*3*(5+3)==24*pi and f2(24*pi)=='75.40'
# ৪ গোলক
A,B=(1,2),(7,10); assert D(A,B)==10 and (R(1+7,2),R(2+10,2))==(4,6)
assert 4*pi*25==100*pi and R(4,3)*pi*125==R(500,3)*pi and f2(100*pi)=='314.16' and f2(R(500,3)*pi)=='523.60'
assert sqrt(25-9)==4 and f2(16*pi)=='50.27'
# ৫ ঘনকে গোলক
Q=[(-3,-1),(3,-1),(3,5),(-3,5)]; assert all(D(Q[i],Q[(i+1)%4])==6 for i in range(4)) and D(Q[0],Q[2])==D(Q[1],Q[3])==6*sqrt(2) and Ar(*Q)==36
assert 216-R(4,3)*pi*27==216-36*pi and f2(216-36*pi)=='102.90'
# ৬ সুষম চতুস্তলক
A,B,C=(1,1),(9,1),(5,1+4*sqrt(3)); assert D(A,B)==8 and simplify(D(B,C)-8)==0 and simplify(D(A,C)-8)==0
assert simplify(Ar(A,B,C)-16*sqrt(3))==0 and simplify((C[1]-B[1])/(C[0]-B[0])+sqrt(3))==0
assert simplify(4*16*sqrt(3)-64*sqrt(3))==0 and f2(64*sqrt(3))=='110.85' and simplify(R(512)/(6*sqrt(2))-R(128,3)*sqrt(2))==0 and f2(R(128,3)*sqrt(2))=='60.34'

